"""Apply translations for invoice_audit_report_v2.html new strings."""
import polib
AR_PATH = 'locale/ar/LC_MESSAGES/django.po'
EN_PATH = 'locale/en/LC_MESSAGES/django.po'

AR = {
    'FinAI Audit System — Tadgeeg': 'نظام تدقيق المالي — تدقيق',
    'Decision-Focused Audit Brief': 'ملخّص تدقيق موجّه نحو القرار',
    'Supplier': 'المورد',
    'REVIEW': 'مراجعة',
    'NEW': 'جديد',
    'Generated by FinAI Audit System — Tadgeeg': 'تم إنشاء هذا التقرير بواسطة نظام تدقيق المالي — تدقيق',
    'Download PDF': 'تنزيل PDF',
    'Compliance Score': 'درجة الامتثال',
    'By': 'بواسطة',
    'Total Amount (%(v0)s)': 'إجمالي المبالغ (%(v0)s)',
    'Recommended Decision': 'القرار الموصى به',
    'No key findings': 'لا توجد اكتشافات رئيسية',
    'Exposure Ratio': 'نسبة التعرّض',
    'No additional insights': 'لا توجد رؤى إضافية',
    'Actionable Recommendations': 'توصيات قابلة للتنفيذ',
    'No recommendations at this time': 'لا توجد توصيات حالياً',
    'Compliance Engine': 'محرّك الامتثال',
    'checks passed': 'فحوصات ناجحة',
    'Overall Score': 'الدرجة الإجمالية',
    'Header': 'الرأس',
    'Financial Control': 'الضبط المالي',
    'Document Quality': 'جودة المستند',
    'of %(v0)s rules': 'من %(v0)s قاعدة',
    'No compliance data': 'لا توجد بيانات امتثال',
    'High-Risk Invoices': 'الفواتير عالية المخاطرة',
    'Failed Rules Analysis': 'تحليل القواعد الفاشلة',
    'rules': 'قواعد',
    'Failures': 'الإخفاقات',
    'Fail Rate': 'معدّل الإخفاق',
    'Supplier Analysis': 'تحليل الموردين',
    'suppliers': 'موردون',
    'Share %%': 'الحصة %%',
    'Risk Tier': 'فئة المخاطرة',
    'Flags': 'علامات',
    'Dominant Supplier': 'المورد المهيمن',
    'Represents': 'يمثّل',
    'of total spend': 'من إجمالي الإنفاق',
    'Top Anomaly Patterns': 'أبرز أنماط الشذوذ',
    'Actions & Recommendations': 'الإجراءات والتوصيات',
}

ar = polib.pofile(AR_PATH)
applied = 0
missing = []
for entry in ar:
    if entry.obsolete or entry.msgid_plural:
        continue
    is_fuzzy = 'fuzzy' in entry.flags
    is_empty = not entry.msgstr and entry.msgid != ""
    if not (is_fuzzy or is_empty):
        continue
    if entry.msgid in AR:
        entry.msgstr = AR[entry.msgid]
        if is_fuzzy:
            entry.flags = [f for f in entry.flags if f != 'fuzzy']
            entry.previous_msgid = None
            entry.previous_msgctxt = None
        applied += 1
    else:
        missing.append(entry.msgid)
ar.save(AR_PATH)
print(f"AR applied: {applied}, missing: {len(missing)}")
for m in missing:
    print(f"  MISS: {m!r}")

en = polib.pofile(EN_PATH)
fixed = 0
for entry in en:
    if entry.obsolete or entry.msgid_plural:
        continue
    is_fuzzy = 'fuzzy' in entry.flags
    is_empty = not entry.msgstr and entry.msgid != ""
    if is_fuzzy or is_empty:
        entry.msgstr = entry.msgid
        if is_fuzzy:
            entry.flags = [f for f in entry.flags if f != 'fuzzy']
            entry.previous_msgid = None
            entry.previous_msgctxt = None
        fixed += 1
en.save(EN_PATH)
print(f"EN fixed: {fixed}")

for path, name in [(AR_PATH, 'AR'), (EN_PATH, 'EN')]:
    p = polib.pofile(path)
    e = sum(1 for x in p if not x.msgstr and not x.obsolete and x.msgid != "" and not x.msgid_plural)
    f = sum(1 for x in p if 'fuzzy' in x.flags and not x.obsolete)
    print(f"{name}: empty={e}, fuzzy={f}")
